def count_sequences(n):
    count = 0
    for d1 in range(1, n - 3):
        for d2 in range(1, n - d1 - 2):
            for d3 in range(1, n - d1 - d2 - 1):
                for d4 in range(1, n - d1 - d2 - d3):
                    d5 = n - (d1 + d2 + d3 + d4)
                    if d5 >= 1:
                        # Check the condition: exactly two of 
                        # d1+d2, d2+d3, d3+d4, d4+d5, d5+d1 are >= 50.5
                        # Since d_i are integers, this is d_i+d_{i+1} >= 51.
                        vals = [d1+d2, d2+d3, d3+d4, d4+d5, d5+d1]
                        if sum(1 for v in vals if v >= 51) == 2:
                            count += 1
    return count

