    # d1+d2+d3+d4+d5 = n
    # This is the number of partitions of n into 5 parts, but order matters.
    # We can use nested loops but we need to be careful about the range.
    for d1 in range(1, n - 3):
        for d2 in range(1, n - d1 - 2):
            for d3 in range(1, n - d1 - d2 - 1):
                for d4 in range(1, n - d1 - d2 - d3):
